import{z as n,x as h,o as A,c as s,q as l,j as r,D as E,d as e,s as o,S as t,b as B}from"./chunks/framework.C8m1ZpeB.js";const g=JSON.parse('{"title":"High-NA 套刻","description":"","frontmatter":{"title":"High-NA 套刻","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/high-na-overlay-na.md","filePath":"litho/high-na-overlay-na.md","lastUpdated":1791413859000}'),p={name:"litho/high-na-overlay-na.md"};function D(d,a,F,m,N,c){const i=h("Mermaid");return A(),s("div",null,[a[2]||(a[2]=l('<h1 id="high-na-套刻" tabindex="-1">High-NA 套刻 <a class="header-anchor" href="#high-na-套刻" aria-label="Permalink to &quot;High-NA 套刻&quot;">​</a></h1><div class="epigraph"><p>0.55 把套刻预算收得更紧：半场拼接要场间对准，更薄焦深和变形光学把残差放大成 CD 与通孔覆盖失效。</p><footer>—— 归纳自 ASML 对 High-NA / EXE 套刻与拼接挑战的公开描述</footer></div><p><a href="/litho/high-na-stitch">上一课</a>把大 die 写成两次半场曝光和一条缝。缺口是：缝上的场间对准只是套刻账的一页——层间 overlay、匹配机台、变形畸变和离焦引起的表观位移，在 NA 0.55 下同时变苛刻。本课钉 High-NA 套刻。胶厚与焦深如何抢同一段 \\(z\\) 预算，留给<a href="/litho/high-na-resist-budget">下一课</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><a href="/litho/litho-overlay">套刻</a> 的定义没变：本层相对下层（或同层另一次曝光）的位置残差。变的是公差与来源权重。节距随 0.55/0.33 约缩到 60%，通孔覆盖窗口按面积更苛刻。拼接引入「场 A 对场 B」这一项，NXE 全场产品没有。变形光学让 X/Y 倍率不同，畸变、放大和扫描同步误差要分轴建模，不能用各向同性 4× 的高阶 overlay 多项式原样搬过来。</p><p><span class="marginnote">术语翻译：通孔覆盖是「本层的孔要正好落在下一层金属线上」的判据。孔往往比线还小几纳米，位置错一点孔就切到线外，电接触直接断——它是套刻里最苛刻的一页成绩单，比线宽敏感得多。</span></p><p>ASML 公开把 overlay 与 stitching 写成 High-NA 量产导入的核心挑战之一，与源功率、pellicle、胶并列，而不是「NA 高了自然更准」。本课描述这条挑战结构，不编造 EXE 的纳米规格表。</p><h3 id="焦深把套刻和-cd-焊在一起" tabindex="-1">焦深把套刻和 CD 焊在一起 <a class="header-anchor" href="#焦深把套刻和-cd-焊在一起" aria-label="Permalink to &quot;焦深把套刻和 CD 焊在一起&quot;">​</a></h3><p>DOF \\(\\propto\\lambda/\\mathrm{NA}^2\\)，0.55 相对 0.33 大约按 \\((0.33/0.55)^2\\approx 0.36\\) 变薄。硅片不平整、卡盘指纹、掩模热，都会让局部离焦。非理想远心或残差倾斜时，离焦表现为 CD 兼表观位移。High-NA 上「只看 overlay 标记、不问焦」会漏掉通孔覆盖的真实失效。磁浮台与调焦带宽必须进入同一份预算。</p><p><span class="marginnote">数字实例：焦深按 \\(\\lambda/\\mathrm{NA}^2\\) 缩，从 0.33 换到 0.55 就是乘 \\((0.33/0.55)^2\\approx 0.36\\)。假设原来有 100 nm 的焦深预算，现在只剩约 36 nm——几纳米的硅片不平或一颗指纹的厚度就能吃掉一大块，离焦因此成了套刻账里的常驻项。</span></p><p><span class="marginnote">单机套刻、匹配套刻、产品上套刻三种定义仍然适用。High-NA 导入期最容易把开发机上的单机数当成 HVM 产品上套刻。公开挑战描述针对的是后者。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对准传感器、编码器网格和双台策略继承真空 Twinscan，但网格密度、热校正和变形场模型按 EXE 重写。拼接层：先套下层，再套邻场，校正环要能同时收平移/放大/旋转与缝上的高阶跳变。交叉匹配：同一节点里 NXE 与 EXE 混跑时，DUV–EUV 那套 cross-match 还要加上 0.33–0.55 的光学指纹差。</p><p>计量：缝上专用标记、场内高阶、以及与 CD-SEM 的覆盖相关性。只优化标记 overlay 而通孔链失效，说明标记与器件的 M3D/阴影不同——<a href="/litho/euv-oblique-shadow">斜入射</a> 的警告在 0.55 更重。计算光刻把 overlay 残差当作热点输入，而不是假设缝上残差为零。</p><p><span class="marginnote">常见误区：初学者容易把「对准标记量准了」当成「器件套准了」。标记与真实器件图形隔着不同的多层堆叠和斜入射阴影，EUV 尤其明显；标记读数很好而通孔已经切到线外，是量产里真实会发生的失效模式。</span></p><h3 id="拼接项与层间项分账" tabindex="-1">拼接项与层间项分账 <a class="header-anchor" href="#拼接项与层间项分账" aria-label="Permalink to &quot;拼接项与层间项分账&quot;">​</a></h3><p>场间（stitch）overlay 坏，同一层金属在缝上错位或双线。层间 overlay 坏，通孔落在下层线外。两者可以同时超，来源不同：前者是两次半场的对准与掩模匹配；后者含工艺变形、下层标记质量和镜头匹配。预算必须拆开，否则会拧错校正。</p>',17)),(A(),r(t,null,{default:E(()=>[o(i,{id:"mermaid-49",class:"mermaid",graph:"flowchart%20TD%0A%20%20ST%5B%22%E5%8D%8A%E5%9C%BA%E6%8B%BC%E6%8E%A5%E5%9C%BA%E9%97%B4%22%5D%20--%3E%20OV%5B%22%E4%BA%A7%E5%93%81%E4%B8%8A%E5%A5%97%E5%88%BB%22%5D%0A%20%20IL%5B%22%E5%B1%82%E9%97%B4%E5%AF%B9%E5%87%86%22%5D%20--%3E%20OV%0A%20%20NA%5B%22NA%200.55%20%E6%9B%B4%E8%96%84%20DOF%22%5D%20--%3E%20APP%5B%22%E7%A6%BB%E7%84%A6%E8%A1%A8%E8%A7%82%E4%BD%8D%E7%A7%BB%22%5D%0A%20%20AN%5B%22%E5%8F%98%E5%BD%A2%E5%88%86%E8%BD%B4%E7%95%B8%E5%8F%98%22%5D%20--%3E%20OV%0A%20%20APP%20--%3E%20OV%0A%20%20OV%20--%3E%20Y%5B%22%E9%80%9A%E5%AD%94%E8%A6%86%E7%9B%96%20%2F%20%E7%BC%9D%E4%B8%8A%E8%BF%9E%E7%BB%AD%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=B("h2",{id:"机制",tabindex:"-1"},[e("机制 "),B("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=B("p",null,"更高 NA 提高光学对比，有助于某些层的套准读出，但目标图形更小，同样纳米残差的相对伤害更大。变形使扫描向与狭缝向的掩模台速度比不同（4× vs 8× 几何），同步误差投影到硅片时分轴加权。热：更大镜子、更高功率密度，掩模与镜头漂移更快，动态 overlay 进扫描。随机孔位置抖动看起来像 overlay，根子是光子/化学，修对准网格无效。",-1)),(A(),r(t,null,{default:E(()=>[o(i,{id:"mermaid-56",class:"mermaid",graph:"flowchart%20TD%0A%20%20SYMPTOM%5B%22%E9%80%9A%E5%AD%94%E8%A6%86%E7%9B%96%20%2F%20%E7%BC%9D%E4%B8%8A%E5%A4%B1%E6%95%88%22%5D%20--%3E%20KIND%7B%22%E6%AE%8B%E5%B7%AE%E6%98%AF%E7%B3%BB%E7%BB%9F%E6%80%A7%E8%BF%98%E6%98%AF%E9%9A%8F%E6%9C%BA%EF%BC%9F%22%7D%0A%20%20KIND%20--%20%22%E7%B3%BB%E7%BB%9F%E6%80%A7%EF%BC%88%E5%8F%AF%E6%8B%9F%E5%90%88%EF%BC%89%22%20--%3E%20GRID%5B%22%E5%AF%B9%E5%87%86%E7%BD%91%E6%A0%BC%EF%BC%9A%E5%B9%B3%E7%A7%BB%20%2F%20%E6%94%BE%E5%A4%A7%20%2F%20%E6%97%8B%E8%BD%AC%20%2F%20%E9%AB%98%E9%98%B6%22%5D%0A%20%20GRID%20--%3E%20ANISO%7B%22%E5%8F%98%E5%BD%A2%E5%85%89%E5%AD%A6%E5%88%86%E8%BD%B4%EF%BC%9F%22%7D%0A%20%20ANISO%20--%20%22%E6%98%AF%22%20--%3E%20SPLIT%5B%22X%2FY%20%E5%88%86%E8%BD%B4%E5%BB%BA%E6%A8%A1%EF%BC%8C4%C3%97%20%E4%B8%8E%208%C3%97%20%E5%88%86%E5%BC%80%E5%8A%A0%E6%9D%83%22%5D%0A%20%20KIND%20--%20%22%E9%9A%8F%E7%A6%BB%E7%84%A6%E6%BC%82%E7%A7%BB%22%20--%3E%20DEFOC%5B%22%E7%A6%BB%E7%84%A6%E8%A1%A8%E8%A7%82%E4%BD%8D%E7%A7%BB%EF%BC%9A%E4%B8%8E%20DOF%E3%80%81%E8%B0%83%E7%84%A6%E5%B8%A6%E5%AE%BD%E8%81%94%E7%AB%8B%22%5D%0A%20%20KIND%20--%20%22%E9%9A%8F%E6%9C%BA%EF%BC%88%E5%AD%94%E4%BD%8D%E6%8A%96%E5%8A%A8%EF%BC%89%22%20--%3E%20RAND%5B%22%E5%85%89%E5%AD%90%20%2F%20%E5%8C%96%E5%AD%A6%E6%95%A3%E7%B2%92%E6%BA%90%EF%BC%9A%E4%BF%AE%E5%AF%B9%E5%87%86%E7%BD%91%E6%A0%BC%E6%97%A0%E6%95%88%22%5D%0A%20%20THERM%5B%22%E6%8E%A9%E6%A8%A1%20%2F%20%E9%95%9C%E5%A4%B4%E7%83%AD%E6%BC%82%E7%A7%BB%22%5D%20--%3E%20DYN%5B%22%E5%8A%A8%E6%80%81%20overlay%EF%BC%9A%E6%89%AB%E6%8F%8F%E4%B8%AD%E8%A1%A5%E5%81%BF%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=l('<p>工厂经济：High-NA 单次省下的双重套刻层，可能被拼接层和更严的产品上套刻部分吃回。ASML 的公开叙事是挑战可管理、需整机与工艺一起资格认证，而不是「0.55 自动优于双重 0.33 的套刻」。</p><p><span class="marginnote">不要把 NXT 浸没产品页上的 overlay 纳米数抄到 EXE 上当结论。平台、真空、变形、半场都不同。本课只用公开的挑战描述：拼接 + 更高 NA + 更薄焦深。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不编造 EXE:5000/5200 的 overlay 规格，不把投资者日上某一代配置产能与套刻捆成课后答案。也不重写对准传感器光学。后课默认：说到 High-NA 良率，套刻账含缝、层间、分轴畸变和离焦耦合。胶厚预算从焦深侧再切一刀。</p><p>出处：ASML High-NA / EXE 对 overlay 与 stitching 的公开挑战描述；van Schoot 场几何；套刻定义见 overlay 课。磁浮台细节见已有工件台课。</p><p><span class="marginnote">芯粒若避开拼接，场间项消失，层间与 DOF 项仍在。套刻挑战不是「只有大芯片才有」，只是大芯片多一页缝。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>High-NA 套刻在更小节距上更苛刻，并新增半场场间项。</li><li>变形光学要求分轴畸变与同步模型，不能搬 NXE 各向同性多项式。</li><li>更薄焦深让离焦变成 CD 与表观位移，必须与 overlay 联立。</li><li>拼接项与层间项分账；随机孔抖不是对准能修的。</li><li>不编造 EXE 纳米规格；下一课从胶厚抢 DOF 写起。</li><li>出处：ASML EXE / High-NA 公开挑战描述；van Schoot。</li></ul>',8))])}const u=n(p,[["render",D]]);export{g as __pageData,u as default};
